head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > M > getValue]<br/>Textarea 컴포넌트의 실제 입력값을 반환합니다.",
    "validation" : [
        "Textarea 컴포넌트에 입력된 실제 값을 String 타입으로 반환합니다.",
        "값이 비어 있으면 빈 문자열('') 을 반환합니다.",
        "줄바꿈(\\n) 문자가 포함된 입력값도 그대로 반환합니다.",
        "maxlength 속성으로 초과분이 자동으로 잘린 경우, 잘린 후의 실제 값을 반환합니다.",
        "maxByteLength 속성으로 초과분이 자동으로 잘린 경우, 잘린 후의 실제 값을 반환합니다.",
        "placeholder 가 표시된 상태(미입력 상태)에서는 빈 문자열('') 을 반환합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.getValue = function (target) {
    let rtn = target.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("getValue : [" + rtn + "] (type=" + typeof rtn + ", length=" + rtn.length + ")");
}



// target1 (일반 텍스트 입력값 반환)
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("abc123ABC");
    target1.focus();
};

scwin.btn_getValue1_onclick = function (e) {
    scwin.getValue(target1);
}


// target2 (빈 값 → 빈 문자열 '' 반환)
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("");
    target2.focus();
};

scwin.btn_getValue2_onclick = function (e) {
    scwin.getValue(target2);
}


// target3 (줄바꿈 포함 입력값 그대로 반환)
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("first line\nsecond line\nthird line");
    target3.focus();
};

scwin.btn_getValue3_onclick = function (e) {
    scwin.getValue(target3);
}


// target4 (maxlength=5, 'abcdefg' 입력 → 'abcde'(5자) 잘린 실제 값 반환)
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue("abcdefg");
    target4.focus();
};

scwin.btn_getValue4_onclick = function (e) {
    scwin.getValue(target4);
}


// target5 (maxByteLength=6, '가나다라' 입력 → '가나다'(6byte) 잘린 실제 값 반환)
scwin.btn_setValue5_onclick = function (e) {
    target5.setValue("가나다라");
    target5.focus();
};

scwin.btn_getValue5_onclick = function (e) {
    scwin.getValue(target5);
}


// target6 (placeholder 설정, 미입력 상태에서 getValue → '' 반환)
scwin.btn_getValue6_onclick = function (e) {
    scwin.getValue(target6);
}


// target7 (다국어 한글 입력값 반환)
scwin.btn_setValue7_onclick = function (e) {
    target7.setValue("가나다라마");
    target7.focus();
};

scwin.btn_getValue7_onclick = function (e) {
    scwin.getValue(target7);
}


// target8 (특수문자 포함 입력값 반환)
scwin.btn_setValue8_onclick = function (e) {
    target8.setValue("!@#$%^&*()_+-=");
    target8.focus();
};

scwin.btn_getValue8_onclick = function (e) {
    scwin.getValue(target8);
}
